#!/usr/bin/env python3
"""Extract titles and abstracts from all PDF, DOCX, PPTX files."""
import os
import sys
import json
import PyPDF2
import zipfile
import xml.etree.ElementTree as ET

WORKDIR = "/Users/wangjinhua/Library/Caches/VistaExperiments/formal-task005-local-3x3-minimaxm3-20260824-03-noskill-replicate-01-attempt-01/workspace"

def extract_pdf_text(path, max_pages=2):
    """Extract text from first max_pages pages of PDF."""
    try:
        with open(path, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            text_parts = []
            n = min(max_pages, len(reader.pages))
            for i in range(n):
                try:
                    page_text = reader.pages[i].extract_text()
                    text_parts.append(page_text or "")
                except Exception as e:
                    text_parts.append(f"[ERR: {e}]")
            return "\n".join(text_parts)
    except Exception as e:
        return f"[PDF ERR: {e}]"

def extract_docx_text(path):
    """Extract text from DOCX (it's a zip with word/document.xml)."""
    try:
        with zipfile.ZipFile(path, 'r') as z:
            with z.open('word/document.xml') as f:
                tree = ET.parse(f)
                root = tree.getroot()
                # extract all text
                texts = []
                for elem in root.iter():
                    if elem.tag.endswith('}t') and elem.text:
                        texts.append(elem.text)
                return " ".join(texts)
    except Exception as e:
        return f"[DOCX ERR: {e}]"

def extract_pptx_text(path):
    """Extract text from PPTX (zip with ppt/slides/*.xml)."""
    try:
        all_text = []
        with zipfile.ZipFile(path, 'r') as z:
            slide_files = sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')])
            for sf in slide_files:
                with z.open(sf) as f:
                    tree = ET.parse(f)
                    root = tree.getroot()
                    slide_text = []
                    for elem in root.iter():
                        if elem.tag.endswith('}t') and elem.text:
                            slide_text.append(elem.text)
                    all_text.append(" ".join(slide_text))
        return "\n".join(all_text)
    except Exception as e:
        return f"[PPTX ERR: {e}]"

def main():
    files_meta = {}
    for fn in sorted(os.listdir(WORKDIR)):
        fpath = os.path.join(WORKDIR, fn)
        if not os.path.isfile(fpath):
            continue
        if fn == 'task.md':
            continue
        if fn.endswith('.pdf'):
            text = extract_pdf_text(fpath)
        elif fn.endswith('.docx'):
            text = extract_docx_text(fpath)
        elif fn.endswith('.pptx'):
            text = extract_pptx_text(fpath)
        else:
            continue
        files_meta[fn] = text
    out_path = os.path.join(WORKDIR, "_extracted.json")
    with open(out_path, 'w') as f:
        json.dump(files_meta, f, indent=2)
    print(f"Extracted text from {len(files_meta)} files -> {out_path}")

if __name__ == "__main__":
    main()

